  function cs99T(key,values={}){let value=cs99Text[key]||key;for(const[k,v]of Object.entries(values))value=value.replaceAll('{'+k+'}',String(v));return value;}
  function cs99Button(action,label,kind='bc-primary',disabled=false){return btn('cs99-'+action,esc(label),label,kind,disabled?'disabled':'');}
  function cs99Card(body){return `<section class="cs99-card">${body}</section>`;}
  function cs99Row(name,role,self=false,remove=false){return `<div class="cs99-member"><span class="cs99-avatar">${esc(name[0])}</span><div><b>${esc(name)}${self?` <small>(${esc(cs99T('sharedMembersYou'))})</small>`:''}</b><small>${esc(name.toLowerCase())}@example.invalid</small></div><span class="cs99-role">${esc(cs99T(role==='owner'?'sharedRoleOwner':'sharedRoleEditor'))}</span>${remove?`<button aria-label="${esc(cs99T('sharedMembersRemoveCta'))}" data-action="cs99-remove">${icon('user-minus')}</button>`:''}</div>`;}
  function cs99Health(){const rows=['Tx','Attachment','Budget','Tx','Attachment','CategoryIcon','Budget','Account','Category','Tag'];return cs99Card(`<div class="cs99-heading">${icon('cloud')}<h3>${esc(cs99T('syncHealthTitle'))}</h3><span class="d104-sync-state ${state.cs99Error?'error':''}">${icon(state.cs99Error?'circle-alert':'check')}${esc(cs99T(state.cs99Error?'commonError':'syncHealthInSync'))}</span>${cs99Button('retry',cs99T('v4RecordingRetry'),'bc-secondary')}</div>${state.cs99Error?`<p class="cs99-error" role="status">${esc(state.cs99Error)}</p>`:`<p class="cs99-muted">${esc(cs99T('syncHealthInSync'))}</p>${rows.map((key,i)=>`${[0,3].includes(i)?`<h4>${esc(cs99T(i===0?'syncHealthGroupCurrentLedger':'syncHealthGroupAll'))}</h4>`:''}<div class="cs99-count"><span>${esc(cs99T('syncHealthRow'+key))}</span><span>${esc(cs99T('syncHealthValue',{local:i===0?27:i===3?31:2,remote:i===0?27:i===3?31:2}))}</span></div>`).join('')}<div class="cs99-count"><span>${esc(cs99T('syncHealthRowUnpushed'))}</span><span>0</span></div>`}`);}
  function cs99Invite(){if(state.cs99Generated)return cs99Card(`<div class="cs99-code">ABC 234</div><p class="cs99-muted cs99-center">${esc(cs99T('sharedInviteExpiresAt',{time:'2026-10-28 09:41'}))}</p><div class="cs99-actions">${cs99Button('copy',cs99T('sharedInviteCopyCode'),'bc-secondary')}${cs99Button('share',cs99T('sharedInviteShareLink'))}${cs99Button('copy-link',cs99T('sharedInviteCopyLink'),'bc-secondary')}</div><p class="cs99-muted">${esc(cs99T('sharedInviteInstruction'))}</p>${cs99Button('another',cs99T('sharedInviteGenerateAnother'),'bc-secondary')}`);return cs99Card(`<h4>${esc(cs99T('sharedInviteFormRole'))}</h4><span class="cs99-role">${esc(cs99T('sharedRoleEditor'))}</span><h4>${esc(cs99T('sharedInviteFormExpiry'))}</h4><div class="cs99-options">${[24,72,168].map(hours=>`<button data-action="cs99-expiry-${hours}" aria-pressed="${state.cs99Hours===hours}" class="${state.cs99Hours===hours?'selected':''}">${esc(cs99T('sharedInviteExpiryDays',{n:hours/24}))}</button>`).join('')}</div>${cs99Button('generate',cs99T('sharedInviteGenerate'))}<p class="cs99-muted">${esc(cs99T('sharedInviteWarning'))}</p>`);}
  function cs99Join(){if(state.cs99Preview)return cs99Card(`<div class="cs99-center">${icon('users')}<p class="cs99-muted">${esc(cs99T('sharedJoinInvitedBy',{name:'Owner QA'}))}</p><h2>Shared book</h2><span class="cs99-role">${esc(cs99T('sharedJoinRoleLine',{role:cs99T('sharedRoleEditor')}))}</span><p class="cs99-muted">${esc(cs99T('sharedJoinExpiresInDays',{days:3}))}</p></div><div class="cs99-actions">${cs99Button('cancel-preview',cs99T('commonCancel'),'bc-secondary')}${cs99Button('accept',cs99T('sharedJoinAcceptButton'), 'bc-primary',!!state.cs99Busy)}</div><p class="cs99-muted cs99-center">2026-10-28 09:41</p>`);return cs99Card(`<h3>${esc(cs99T('sharedJoinEnterCode'))}</h3><p class="cs99-muted">${esc(cs99T('sharedJoinEnterCodeHint'))}</p><input class="cs99-input" maxlength="7" data-cs99-code aria-label="${esc(cs99T('sharedJoinEnterCode'))}" placeholder="ABC 234" value="${esc(state.cs99Code||'')}" autocomplete="off">${state.cs99Error?`<p class="cs99-error" role="status">${esc(state.cs99Error)}</p>`:''}${cs99Button('preview',cs99T('sharedJoinPreviewButton'))}`);}
  function cs99Members(key){if(key.endsWith('loading'))return `<div class="cs99-empty" role="status">${icon('loader-circle')}</div>`;if(state.cs99Error)return cs99Card(`<p class="cs99-error">${esc(state.cs99Error)}</p>${cs99Button('retry',cs99T('v4RecordingRetry'))}`);const owner=state.cs99Role==='owner';return cs99Card(cs99Row('Alex',owner?'owner':'editor',true)+(!state.cs99Removed?cs99Row('Blair','editor',false,owner):''))+cs99Card(owner?cs99Button('invite',cs99T('sharedMembersInviteCta'),'bc-secondary'):cs99Button('leave',cs99T('sharedMembersLeaveCta'),'bc-secondary'));}
  function cs99Stats(key){const picker=`<div class="cs99-options">${[['month','analyticsMonth'],['year','analyticsYear'],['all','analyticsAll']].map(([scope,label])=>`<button data-action="cs99-scope-${scope}" aria-pressed="${scope===state.cs99Scope}" class="${scope===state.cs99Scope?'selected':''}">${esc(cs99T(label))}</button>`).join('')}</div>`;if(state.cs99Error)return picker+cs99Card(`<p class="cs99-error">${esc(state.cs99Error)}</p>${cs99Button('retry',cs99T('v4RecordingRetry'))}`);if(key.endsWith('empty'))return picker+`<div class="cs99-empty">${esc(cs99T('sharedMembersStatsEmpty'))}</div>`;return picker+cs99Card(`<div class="cs99-summary"><span>${esc(cs99T('sharedMembersStatsIncome'))}<b class="cs99-income">+€133.50</b></span><span>${esc(cs99T('sharedMembersStatsExpense'))}<b class="cs99-expense">−€50.00</b></span></div>`)+cs99Card(cs99Row('Alex','owner')+`<div class="cs99-count"><span>${esc(cs99T('sharedMembersStatsTxCount',{count:2}))}</span><span>+€123.50 · −€20.00 (40%)</span></div>`+cs99Row('Blair','editor')+`<div class="cs99-count"><span>${esc(cs99T('sharedMembersStatsTxCount',{count:3}))}</span><span>+€10.00 · −€30.00 (60%)</span></div>`);}
  function cs99Modal(){const leave=state.cs99Modal==='leave';const title=cs99T(leave?'sharedMembersLeaveTitle':'sharedMembersRemoveTitle');return `<div class="cs99-overlay"><section class="cs99-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3><p>${esc(cs99T(leave?'sharedMembersLeaveConfirm':'sharedMembersRemoveConfirm',{name:leave?'Shared book':'Blair'}))}</p><div class="cs99-actions">${cs99Button('close',cs99T('commonCancel'),'bc-secondary')}${cs99Button(leave?'confirm-leave':'confirm-remove',cs99T(leave?'sharedMembersLeaveCta':'commonRemove'))}</div></section></div>`;}
  function cs99Page(key){let body='';if(key.startsWith('shared-sync'))body=cs99Card(`<div class="cs99-heading">${icon('shield-check')}<b>qa@example.invalid</b></div>`)+cs99Card(`<div class="cs99-heading">${icon('shield-check')}<b>${esc(cs99T('twofaStatusTitle'))} · ${esc(cs99T('twofaStatusEnabled'))}</b></div>`)+cs99Health()+cs99Card(`<details><summary>${esc(cs99T('cloudSyncHelpTitle'))}</summary>${['Modes','WhenFull','Stuck','Troubleshoot'].map(x=>`<h4>${esc(cs99T('cloudSyncHelp'+x+'Title'))}</h4><p class="cs99-muted">${esc(cs99T('cloudSyncHelp'+x+'Body'))}</p>`).join('')}${cs99Button('logs',cs99T('cloudSyncHelpOpenLogCenter'),'bc-secondary')}</details>`)+`<p class="cs99-muted cs99-center">BeeCount Cloud vqa-1.0</p>`;else if(['shared-invite','shared-code'].includes(key))body=cs99Invite();else if(['shared-join','shared-preview'].includes(key))body=cs99Join();else if(key.startsWith('shared-members'))body=cs99Members(key);else body=cs99Stats(key);return `<div class="cs99-shell">${body}${state.cs99Event?`<p class="cs99-muted" role="status">${esc(state.cs99Event)}</p>`:''}${state.cs99Modal?cs99Modal():''}</div>`;}
  for(const[key,[title,source]]of Object.entries(cs99Routes))fDefine(key,cs99T(title),'共享账本与云同步','cloud/'+source+'.dart',()=>cs99Page(key));
  const cs99Before=fRender;
  fRender=function(key){if(!Object.hasOwn(cs99Routes,key))return cs99Before(key);if(state.cs99Preset!==key){Object.assign(state,{cs99Preset:key,cs99Hours:24,cs99Generated:key==='shared-code',cs99Preview:key==='shared-preview',cs99Role:key.endsWith('editor')?'editor':'owner',cs99Scope:'month',cs99Modal:'',cs99Busy:false,cs99Removed:false,cs99Event:'',cs99Code:'',cs99Error:key.endsWith('error')?'QA 503':''});}return subhead(cs99T(cs99Routes[key][0]))+cs99Page(key);};
  document.addEventListener('input',event=>{if(event.target.matches('[data-cs99-code]'))state.cs99Code=event.target.value.replace(/[\s-]/g,'').toUpperCase();});
  document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!action?.startsWith('cs99-'))return;event.preventDefault();event.stopImmediatePropagation();const command=action.slice(5);if(command.startsWith('expiry-'))state.cs99Hours=Number(command.slice(7));else if(command.startsWith('scope-'))state.cs99Scope=command.slice(6);else if(command==='generate')state.cs99Generated=true;else if(command==='another')state.cs99Generated=false;else if(command==='preview'){state.cs99Error=(state.cs99Code||'').length===6?'':cs99T('sharedJoinCodeFormatError');state.cs99Preview=!state.cs99Error;}else if(command==='cancel-preview')state.cs99Preview=false;else if(command==='accept'&&!state.cs99Busy){state.cs99Busy=true;state.cs99Event=cs99T('sharedJoinSuccess',{name:'Shared book'});}else if(command==='invite')state.page='flow-shared-invite';else if(command==='remove'&&state.cs99Role==='owner')state.cs99Modal='remove';else if(command==='leave'&&state.cs99Role!=='owner')state.cs99Modal='leave';else if(command==='close')state.cs99Modal='';else if(command==='confirm-remove'){state.cs99Removed=true;state.cs99Modal='';state.cs99Event=cs99T('sharedMembersRemoved');}else if(command==='confirm-leave'){state.cs99Modal='';state.cs99Event=cs99T('sharedMembersLeaveDone');}else if(command==='retry')state.cs99Error='';else if(command==='logs')state.page='flow-log-center';else if(['copy','copy-link','share'].includes(command))state.cs99Event='受控示例：'+cs99T(command==='share'?'sharedInviteShareLink':'commonCopied');render();},true);
